#!/usr/bin/env node
'use strict';
//
// issue 2700. CLAUDE.md says commit messages "carry no AI attribution — no session URLs, no
// 'generated by'". Squash merges copy every PR commit's message into the merge commit, so each
// agent commit that carries a harness trailer lands on `main`, where it stays: removing it would
// mean rewriting `main`, which is forbidden. 42 such lines sat in the last 30 commits when this was
// written. The agents' harness asks for the trailers, the repo rule wins, and nothing enforced it.
//
// This reads every commit message on the branch and fails on the three shapes the harness writes.
// Commits only: PR descriptions and GitHub comments are not commit messages and are not read.
//
// issue 2978. The messages are not the only place it comes from. A cloud session commits as
// `Claude <noreply@anthropic.com>`, the container's default identity, and the PR is opened by the
// owner's account. When auto-merge squashes, GitHub adds a `Co-authored-by` line for every commit
// author who is not the PR author, so the trailer reaches `main` although no commit message has it:
// 47 of 82 commits in a week. So the AUTHOR of each commit is read too. An author is attribution when
// its email is the Anthropic noreply address or its name is Claude. (The committer is not read: the
// squash trailer comes from authors, and GitHub's own merge sets the committer.)
//
// Which commits:
//   - CI (`pull_request`): GitHub lists the PR commits; merged main commits stay exempt.
//     Missing commit data fails the check.
//   - Locally, nothing set: `<base>..HEAD`, with the base from the same candidates the ratchets use
//     (origin/main, then main). With no base to be had it says so and passes, since there is
//     nothing to compare against; CI is the gate.
const { spawnSync } = require('child_process');

// `Co-authored-by: Delan …` is a person and must pass; only a trailer naming Claude or the Anthropic
// noreply address is attribution.
const PATTERNS = [
  { name: 'AI co-author trailer', re: /^Co-authored-by:.*(Claude|noreply@anthropic\.com)/i },
  { name: 'Claude session URL', re: /claude\.ai\/code\/session_/i },
  { name: '"Generated with/by Claude" line', re: /Generated (with|by) \[?Claude/i },
];

// A person named Claude who is not the tool would trip the name pattern; use `.mailmap` or a different
// commit identity. The email is the reliable half.
const AUTHOR_PATTERNS = [
  { name: 'Anthropic noreply commit author', field: 'authorEmail', re: /noreply@anthropic\.com/i },
  { name: 'commit author named Claude', field: 'authorName', re: /^claude(\s|$)/i },
];

const BASE_CANDIDATES = ['origin/main', 'main'];

/**
 * `[{ sha, subject, line, pattern }]` for every offending line in `[{ sha, message, authorName?,
 * authorEmail? }]`. A commit with no author fields (older callers, a fixture) has none to judge.
 */
function findViolations(commits) {
  const out = [];
  for (const { sha, message, authorName, authorEmail } of commits) {
    const subject = message.split('\n')[0];
    for (const p of AUTHOR_PATTERNS) {
      const value = p.field === 'authorEmail' ? authorEmail : authorName;
      if (typeof value === 'string' && p.re.test(value)) {
        out.push({ sha, subject, line: `${authorName ?? ''} <${authorEmail ?? ''}>`, pattern: p.name });
      }
    }
    for (const line of message.split('\n')) {
      const text = line.replace(/\r$/, '');
      for (const p of PATTERNS) {
        if (p.re.test(text)) out.push({ sha, subject, line: text, pattern: p.name });
      }
    }
  }
  return out;
}

function parseLog(stdout) {
  return stdout
    .split('\x01')
    .map((rec) => rec.replace(/^\n/, ''))
    .filter((rec) => rec.trim() !== '')
    .map((rec) => {
      const [sha, authorName, authorEmail, ...rest] = rec.split('\x00');
      return { sha, authorName, authorEmail, message: rest.join('\x00') };
    });
}

function git(cwd, args) {
  const res = spawnSync('git', args, { cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, windowsHide: true });
  if (res.error) return { ok: false, reason: String(res.error.message) };
  if (res.status !== 0) return { ok: false, reason: (res.stderr || `git exited ${res.status}`).trim().split('\n')[0] };
  return { ok: true, stdout: res.stdout };
}

const LOG_FORMAT = '--format=%H%x00%an%x00%ae%x00%B%x01';

function resolveBase(cwd) {
  for (const ref of BASE_CANDIDATES) {
    if (git(cwd, ['rev-parse', '--verify', '--quiet', `${ref}^{commit}`]).ok) return ref;
  }
  return null;
}

// `GET /pulls/{n}/commits` lists at most 250 commits, 100 a page.
const PR_COMMITS_PER_PAGE = 100;
const PR_COMMITS_MAX_PAGES = 3;

/** The PR's own commits as GitHub lists them. `fetchImpl` is the tests' seam. */
async function fetchPrCommits({ repo, number, token, apiUrl, fetchImpl }) {
  const commits = [];
  for (let page = 1; page <= PR_COMMITS_MAX_PAGES; page++) {
    const url = `${apiUrl}/repos/${repo}/pulls/${number}/commits?per_page=${PR_COMMITS_PER_PAGE}&page=${page}`;
    const headers = { Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' };
    if (token) headers.Authorization = `Bearer ${token}`;
    let body;
    try {
      const res = await fetchImpl(url, { headers });
      if (!res.ok) return { error: `could not list the PR's commits (${url}): HTTP ${res.status}` };
      body = await res.json();
    } catch (e) {
      return { error: `could not list the PR's commits (${url}): ${e && e.message ? e.message : e}` };
    }
    if (!Array.isArray(body)) return { error: `could not list the PR's commits (${url}): the response is not a list` };
    for (const c of body) {
      if (!c || typeof c.sha !== 'string' || !c.commit || typeof c.commit.message !== 'string') {
        return { error: `could not list the PR's commits (${url}): an entry has no sha or message` };
      }
      const author = c.commit.author && typeof c.commit.author === 'object' ? c.commit.author : {};
      commits.push({ sha: c.sha, message: c.commit.message, authorName: author.name, authorEmail: author.email });
    }
    if (body.length < PR_COMMITS_PER_PAGE) break;
  }
  return { commits };
}

/** @returns {Promise<{ commits: Array, label: string } | { skip: string } | { error: string }>} */
async function collectCommits(cwd, env, fetchImpl = globalThis.fetch) {
  if (env.PR_NUMBER) {
    const number = Number(env.PR_NUMBER);
    if (!Number.isInteger(number) || number < 1) return { error: `PR_NUMBER is not a positive integer (${env.PR_NUMBER})` };
    if (!env.GITHUB_REPOSITORY) return { error: 'PR_NUMBER is set but GITHUB_REPOSITORY is not' };
    const got = await fetchPrCommits({
      repo: env.GITHUB_REPOSITORY,
      number,
      token: env.GH_TOKEN || env.GITHUB_TOKEN,
      apiUrl: env.GITHUB_API_URL || 'https://api.github.com',
      fetchImpl,
    });
    if (got.error) return got;
    if (got.commits.length === 0) return { error: `GitHub listed no commits for PR #${number}` };
    return { commits: got.commits, label: `the ${got.commits.length} commit(s) of PR #${number}` };
  }
  const base = resolveBase(cwd);
  if (!base) return { skip: 'no base branch resolved (tried origin/main, main); CI is the gate for this rule.' };
  const log = git(cwd, ['log', LOG_FORMAT, `${base}..HEAD`]);
  if (!log.ok) return { error: `git log ${base}..HEAD failed: ${log.reason}` };
  return { commits: parseLog(log.stdout), label: `${base}..HEAD` };
}

async function main() {
  const repoArg = process.argv.indexOf('--repo');
  const cwd = repoArg >= 0 ? process.argv[repoArg + 1] : process.cwd();
  const got = await collectCommits(cwd, process.env);
  if (got.error) {
    console.error(`check-commit-attribution: ${got.error}`);
    process.exit(1);
  }
  if (got.skip) {
    console.log(`check-commit-attribution: skipped, ${got.skip}`);
    return;
  }
  const violations = findViolations(got.commits);
  if (violations.length === 0) {
    console.log(`check-commit-attribution: ${got.commits.length} commit(s) in ${got.label}, none carries AI attribution.`);
    return;
  }
  console.error('Commits must carry no AI attribution (CLAUDE.md: "no session URLs, no \'generated by\'"), in the message or the author.\n');
  for (const v of violations) {
    console.error(`  commit ${v.sha.slice(0, 10)} "${v.subject}"\n    ${v.pattern}: ${v.line}\n`);
  }
  const byAuthor = violations.some((v) => AUTHOR_PATTERNS.some((p) => p.name === v.pattern));
  const byMessage = violations.some((v) => PATTERNS.some((p) => p.name === v.pattern));
  if (byMessage) {
    console.error(
      'A message: delete those lines from the commit message. On your own unpushed branch, run\n' +
      '`git commit --amend` for the latest commit, or `git rebase -i origin/main` and reword the older\n' +
      'ones. A new commit cannot fix an old message, so rewrite your OWN branch before it is merged.\n' +
      'Never rewrite `main`. Your harness may ask for these trailers; this repo\'s rule overrides it.\n'
    );
  }
  if (byAuthor) {
    console.error(
      'An author: GitHub turns every commit author who is not the PR author into a `Co-authored-by: Claude`\n' +
      'line on `main` when it squashes, whatever the messages say. Set the repo\'s agent identity first:\n' +
      '  git config user.name "nekodas-neko"\n' +
      '  git config user.email "279847013+nekodas-neko@users.noreply.github.com"\n' +
      '(the cloud session-start hook does this for you in new sessions). Then, unpushed: `git commit --amend\n' +
      '--reset-author --no-edit` (or `git rebase origin/main --exec "git commit --amend --reset-author --no-edit"`).\n' +
      'Already pushed: do not force-push. Start a fresh branch from origin/main with the identity set, bring\n' +
      'the work over with `git cherry-pick -n <sha>...`, commit, and open the PR from the new branch.'
    );
  }
  process.exit(1);
}

if (require.main === module) {
  main().catch((e) => {
    console.error(`check-commit-attribution: ${e && e.stack ? e.stack : e}`);
    process.exit(1);
  });
}

module.exports = { PATTERNS, AUTHOR_PATTERNS, findViolations, parseLog, collectCommits };
